const items = $input.all();
const today = new Date().toISOString().split('T')[0];

const habits = items.map(item => {
  const props = item.json.properties || {};
  const name = props['Name']?.title?.map(t => t.plain_text).join('') || 'Unknown';
  const completed = props['Completed']?.checkbox || false;
  const streak = props['Streak']?.number || 0;
  const lastDate = props['Last Completed']?.date?.start || '';

  let newStreak = streak;
  if (completed) {
    if (lastDate === today || !lastDate) {
      newStreak = streak + 1;
    }
  } else {
    newStreak = 0;
  }

  return { name, completed, streak: newStreak, previousStreak: streak, pageId: item.json.id };
});

const totalHabits = habits.length;
const completedToday = habits.filter(h => h.completed).length;
const completionRate = totalHabits > 0 ? Math.round((completedToday / totalHabits) * 100) : 0;
const longestStreak = Math.max(...habits.map(h => h.streak), 0);
const bestHabit = habits.reduce((best, h) => h.streak > (best?.streak || 0) ? h : best, habits[0]);

const summary = habits.map(h =>
  `${h.completed ? '✅' : '❌'} ${h.name}: ${h.streak} day streak`
).join('\n');

return [{
  json: {
    date: today,
    totalHabits,
    completedToday,
    completionRate,
    longestStreak,
    bestHabit: bestHabit?.name || 'None',
    summary,
    habits
  }
}];

